const body = $input.item.json.body;

// Only process opened/synchronize/reopened Renovate PRs
const validActions = ['opened', 'synchronize', 'reopened'];
const isRenovate = body?.pull_request?.user?.login?.toLowerCase().includes('renovate');
const isValidAction = validActions.includes(body?.action);

if (!isRenovate || !isValidAction || !body?.pull_request) {
  return []; // Skip non-Renovate PRs
}

return [{
  json: {
    repo: body.repository.full_name,
    pr_number: body.pull_request.number,
    pr_title: body.pull_request.title,
    pr_body: body.pull_request.body || '(no description)',
    pr_node_id: body.pull_request.node_id,
    head_sha: body.pull_request.head.sha,
    pr_url: body.pull_request.html_url
  }
}];

const prData = $('Filter: Is Renovate PR?').item.json;
const files = $input.all();

// Build file summary (truncate large diffs)
const filesSummary = files.map(f => {
  const file = f.json;
  const patch = file.patch || '(binary or no diff)';
  const truncatedPatch = patch.length > 2000 ? patch.substring(0, 2000) + '\n... (truncated)' : patch;
  return `### ${file.filename} (${file.status})\n+${file.additions} -${file.deletions}\n\`\`\`diff\n${truncatedPatch}\n\`\`\``;
}).join('\n\n');

return [{
  json: {
    ...prData,
    files_summary: filesSummary,
    total_files: files.length,
    filenames: files.map(f => f.json.filename).join(', ')
  }
}];

