const response = $input.item.json;
const prData = $('Build Claude Prompt').item.json;

let parsed;
try {
  const text = response.choices[0].message.content.trim();
  // Strip markdown code blocks if Claude wraps it
  const jsonStr = text.replace(/^```json?\n?/, '').replace(/\n?```$/, '');
  parsed = JSON.parse(jsonStr);
} catch(e) {
  // Fallback: don't auto-approve on parse failure
  parsed = {
    decision: 'reject',
    confidence: 'low',
    summary: 'AI response kon niet worden verwerkt',
    concerns: ['Parse fout: ' + e.message],
    comment: '⚠️ De AI review kon niet worden verwerkt. Handmatige review vereist.'
  };
}

return [{
  json: {
    ...prData,
    ai_decision: parsed.decision,
    ai_confidence: parsed.confidence,
    ai_summary: parsed.summary,
    ai_concerns: parsed.concerns || [],
    ai_comment: parsed.comment
  }
}];

